	if a.ensureTick() == nil {
		t.Fatal("a refreshing explorer with no job got no animation chain")
	}
	if a.anim.interval != animationBlinkInterval {
		t.Errorf("chain interval = %v, want the blink interval %v", a.anim.interval, animationBlinkInterval)
	}
