content.content:
// name the activity-column guard (internal/app) knows them by. Only the agents
// table has an activity column: the sessions list is not live.
func (m Model) ActivityTables() map[string]datatable.ActivityTable {
	return map[string]datatable.ActivityTable{"agent-usage/agents": &m.agentTable}
}

// WantsBlink is the router's BlinkingView hook: true while a running agent is
// on screen, so the router frames the view for the dot's blink. A level, not
// an edge: only the agents level, on the Agents tab, and only for the rows the
// filter leaves visible.
func (m Model) WantsBlink() bool {
	if m.level != levelAgents || m.tab != tabAgents {
		return false
	}
	for _, r := range m.agentTable.Visible() {
		if r.state == stateRunning {
			return true
		}
	}
	return false
}

// agentDetail is what the footer says about the selected agent: its state in
}

// status is derived on every frame, with no timer (Rule 128).
//
// The empty sentence needs the listing to be empty in total, not after the
// filter: a filter with no match is not a machine with no sessions.
func (m Model) status() sharedcomponents.Status {
	if m.level == levelAgents {
		return m.agentsStatus()
	}
	switch {
	case m.loadErr:
		return sharedcomponents.Status{
			Text:  "Failed to list Claude Code sessions — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.loading:
		return sharedcomponents.Status{Text: "Reading Claude Code sessions...", Spinner: true}
	case len(m.table.Items()) == 0:
		return sharedcomponents.Status{Text: "No Claude Code sessions found in " + theme.FoldHome(m.root)}
	}
	return sharedcomponents.Status{}
}

// agentsStatus is the footer state of the agents level.
func (m Model) agentsStatus() sharedcomponents.Status {
	switch {
	case m.agentsErr:
		return sharedcomponents.Status{
			Text:  "Failed to read this session — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.agentsLoading:
		return sharedcomponents.Status{Text: "Reading session...", Spinner: true}
	case m.usage.Diagnostics.Degraded():
		return sharedcomponents.Status{
			Text:   "Totals are approximate — some transcript data could not be read",
			Level:  sharedcomponents.LevelWarning,
			Detail: m.agentDetail(),
		}
	}
	st := m.priceHint()
	st.Detail = m.agentDetail()
	return st
}

// priceHint is the footer state about missing prices: where to set them when
// the table is empty, which model lacks one otherwise. It is a state derived on
// every frame, not a message (Rule 128).
func (m Model) priceHint() sharedcomponents.Status {
	if m.prices.Len() == 0 {
		if m.usage.Total().Total() == 0 {
			return sharedcomponents.Status{}
		}
		return sharedcomponents.Status{Text: "Set agent_usage.prices in this context's config file to estimate costs — see ?"}
	}
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		return m.handleResize(msg)
	case sessionListLoadedMsg:
		return m.handleListLoaded(msg)
	case usageDeltaMsg:
		return m.handleUsageDelta(msg)
	case usagePollTickMsg:
		return m.handlePollTick(msg)
	case agentsResumeMsg:
		if m.unfocused {
			return m, nil
		}
		return m.handleResume()
	case shared.TerminalFocusMsg:
		return m.handleTerminalFocus(msg)
	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)
	case jobs.FrameMsg:
		// The router's frame: only the blink phase of the State dot, read at
		// render. The view's footer spinner keeps its own chain.
	m.agentsLoading = false
	return m, pollTickCmd(m.agentGen)
}

// handlePollTick starts the incremental read a tick asks for, unless the tick
// belongs to a superseded chain or a read is already in flight. No spinner:
// polling is silent.
func (m Model) handlePollTick(msg usagePollTickMsg) (tea.Model, tea.Cmd) {
	if msg.gen != m.agentGen || m.level != levelAgents || m.agg == nil || m.reading || m.pollStopped {
		return m, nil
	}
	return m, m.startRead(false)
}

// Leave stops the open session's chain when the router switches away: the new
// generation drops any tick or read still in flight, and nothing is awaited
// any more. The session stays open and coming back resumes it (handleResume).
// A pending ctrl+r is kept, and so is a full read lost in flight (a ctrl+r, or
// the open's first read): the resume repeats it as a full read. It never refuses.
func (m Model) Leave() (tea.Model, tea.Cmd, bool) {
	m.stopChain()
	return m, nil, true
}

// stopChain drops the open session's poll chain, if one is open: the new
// generation ignores any tick or read still in flight. Shared by Leave and a
// terminal blur.
func (m *Model) stopChain() {
	if m.level == levelAgents {
		m.agentGen++
		m.fullPending = m.fullPending || (m.reading && m.agentsLoading)
		m.reading, m.agentsLoading = false, false
	}
}

// handleTerminalFocus suspends the open session's chain on a blur and, on the
// focus edge that follows one, resumes it. A view entering the screen (Resume
// false) only clears the flag: Init's resume starts the read.
func (m Model) handleTerminalFocus(msg shared.TerminalFocusMsg) (tea.Model, tea.Cmd) {
	if !msg.Focused {
		m.unfocused = true
		m.stopChain()
		return m, nil
	}
	m.unfocused = false
	if msg.Resume {
		return m.handleResume()
	}
	return m, nil
}

// handleResume restarts the open session's chain under a new generation, which
// drops the answers of any earlier chain. It reads from the cursor, silently;
// a ctrl+r left pending by Leave becomes a full read, with its spinner.
func (m Model) handleResume() (tea.Model, tea.Cmd) {
	if m.level != levelAgents || m.agg == nil {
		return m, nil
	}
	m.agentGen++
	m.pollStopped = false
	if m.fullPending {
		m.fullPending = false
		return m, tea.Batch(m.startRead(true), m.spinner.Tick)
	}
	return m, m.startRead(false)
}

// startRead marks a read in flight and returns it; full reads everything again.
func (m *Model) startRead(full bool) tea.Cmd {
	c := m.agg.Cursor()
	if full {
		c = c.Rewound()
		m.agentsLoading, m.fullPending, m.pollStopped = true, false, false
	}
	m.reading = true
	return readDeltaCmd(m.agentGen, c)
}

// handlePaste hands pasted text to the filter while it has the keyboard; with
// no field focused a paste is dropped, never read as keys (Rule 111).
func (m Model) handlePaste(msg tea.PasteMsg) (tea.Model, tea.Cmd) {
	if m.InEditMode() {
		return m, m.activeTable(msg)
	}
	return m, nil
}
	m.agg = agentusage.NewAggregate(row.Parent)
	m.fullPending, m.agentsErr = false, false
	m.tab, m.breakdown, m.breakdownTop = tabAgents, breakdown{}, 0
	m.agentTable.FilterBar().ClearSearch() // a filter typed for another session
	m.agentTable.SetItems(nil)
	return m, tea.Batch(m.startRead(true), m.spinner.Tick)
}

// closeAgents returns to the sessions, cursor and filter as they were. Bumping
// agentGen drops a parse still in flight.
func (m Model) closeAgents() (tea.Model, tea.Cmd) {
	m.level = levelSessions
