// the table is empty, which model lacks one otherwise. It is a state derived on
// every frame, not a message (Rule 128).
func (m Model) priceHint() sharedcomponents.Status {
	if m.prices.Len() == 0 {
		if m.usage.Total().Total() == 0 {
