package agentusageview

import (
	"strings"
	"testing"
	"time"

	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-151 step 4: the footer writes the selected agent's state in words
// (the dot repeats it), and the help carries the legend.

// agentDetailer is looked up through an interface so the tests fail on their
// own message before agentDetail exists, not on a compile error.
type agentDetailer interface {
	agentDetail() components.RowDetail
}

func detailOf(t *testing.T, m Model) components.RowDetail {
	t.Helper()
	v, ok := any(m).(agentDetailer)
	if !ok {
		t.Fatal("agentusageview.Model has no agentDetail() components.RowDetail")
	}
	return v.agentDetail()
}

// session at the agents level; alive=false is a paused session.
func sessionOf(t *testing.T, alive bool, agents ...agentusage.Agent) Model {
		msgID, model, in, out)
}

// appendLine appends line and a newline to path.
func appendLine(t *testing.T, path, line string) {
	t.Helper()
	appendRaw(t, path, line+"\n")
}

func appendRaw(t *testing.T, path, s string) {
	t.Helper()
	f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY|os.O_CREATE, 0o600)
	if err != nil {
		t.Error(err)
		return
	}
	defer func() {
		if err := f.Close(); err != nil {
			t.Error(err)
		}
	}()
	if _, err := f.WriteString(s); err != nil {
		t.Error(err)
	}
}

// subDir is the sub-agents directory of the copied session.
func subDir(parent string) string {
	return filepath.Join(strings.TrimSuffix(parent, ".jsonl"), "subagents")
}

// finishTester flips the fixture's one unfinished sub-agent (a02) to finished,
// so nothing keeps the session alive but the recency of its files.
func finishTester(t *testing.T, parent string) {
	t.Helper()
	p := filepath.Join(subDir(parent), "agent-a02.meta.json")
	raw, err := os.ReadFile(p)
	if err != nil {
		t.Fatal(err)
	}
	edited := strings.Replace(string(raw), `"finished":false`, `"finished":true`, 1)
	if edited == string(raw) {
		t.Fatal("the fixture's a02 meta no longer says finished:false")
	}
	if err := os.WriteFile(p, []byte(edited), 0o600); err != nil {
		t.Fatal(err)
	}
}

// ageAll sets every file of the session (and its directories) d in the past.
func ageAll(t *testing.T, parent string, d time.Duration) {
	t.Helper()
	when := time.Now().Add(-d)
	for _, root := range []string{parent, strings.TrimSuffix(parent, ".jsonl")} {
		err := filepath.WalkDir(root, func(p string, _ fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			return os.Chtimes(p, when, when)
		})
		if err != nil {
			t.Fatal(err)
		}
	}
}

// ticksOf keeps the poll ticks among msgs.
func ticksOf(msgs []tea.Msg) []usagePollTickMsg {
	var got []usagePollTickMsg
	for _, m := range msgs {
		if tk, ok := m.(usagePollTickMsg); ok {
			got = append(got, tk)
		}
	}
	return got
// Cmd fails the test instead of hanging it.
func batchMsgs(t *testing.T, cmd tea.Cmd) []tea.Msg {
	t.Helper()
	if cmd == nil {
		return nil
	}
	cmds := []tea.Cmd{cmd}
	if b, ok := cmd().(tea.BatchMsg); ok {
		cmds = b
	}
	out := make(chan tea.Msg, len(cmds))
	for _, c := range cmds {
		go func() {
			if c == nil {
				out <- nil
				return
			}
			out <- c()
		}()
	}
	var msgs []tea.Msg
	for range cmds {
		select {
		case m := <-out:
			msgs = append(msgs, m)
		case <-time.After(5 * time.Second):
			t.Fatal("a Cmd of the batch did not answer")
