func TestTheSessionsListLoadShowsTheActivityDot(t *testing.T) {
	m := newModel(t)
	want := components.Status{Text: "Reading Claude Code sessions...", Activity: true}
	if got := m.status(); got != want {
		t.Fatalf("status() = %+v, want %+v", got, want)
	}
